<?php
require_once __DIR__.'/../identity/OfficePolicy.php';require_once __DIR__.'/SystemLogger.php';
final class ReleaseNotes {
 private PDO $db;private array $builtins;
 public function __construct(PDO $db,?array $builtins=null){$this->db=$db;$this->builtins=$builtins??require __DIR__.'/../../includes/public/builtin_releases.php';}
 public function all():array{$rows=$this->db->query('SELECT version,release_date,title,items_json FROM release_notes')->fetchAll(PDO::FETCH_ASSOC);$out=[];foreach($this->builtins as $r)$out[$r['version']]=$r;foreach($rows as $r){$items=json_decode($r['items_json'],true,512,JSON_THROW_ON_ERROR);$out[$r['version']]=['version'=>$r['version'],'date'=>$r['release_date'],'title'=>$r['title'],'items'=>$items];}$out=array_values($out);usort($out,static fn($a,$b)=>version_compare($b['version'],$a['version']));return $out;}
 public function append(int $actor,array $input):string {
  if(OfficePolicy::actor($this->db,$actor)['role']!=='super_admin')throw new RuntimeException('Only the superadmin can publish patch notes.');
  $text=static function($v,$max){if(!is_string($v)||mb_strlen(trim($v))>$max||preg_match('/[<>\x00-\x08]/u',$v))throw new InvalidArgumentException('Use plain text within the displayed field limits.');return trim($v);};$version=$text($input['version']??'',30);if(!preg_match('/^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/D',$version))throw new InvalidArgumentException('Use a version such as 1.2.4.');$date=$text($input['release_date']??'',10);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('Asia/Manila'));if(!$d||$d->format('Y-m-d')!==$date||$date>(new DateTimeImmutable('today',new DateTimeZone('Asia/Manila')))->format('Y-m-d'))throw new InvalidArgumentException('Choose a valid release date up to today.');$title=$text($input['title']??'',150);if($title==='')throw new InvalidArgumentException('Enter a release title.');$raw=$input['items']??null;if(!is_array($raw)||count($raw)>20)throw new InvalidArgumentException('Add between 1 and 20 changes.');$items=[];foreach($raw as $r){if(!is_array($r))throw new InvalidArgumentException('Invalid change row.');$label=$text($r['label']??'',70);$detail=$text($r['detail']??'',1000);if($label===''&&$detail==='')continue;if($label===''||$detail==='')throw new InvalidArgumentException('Give each change a short label and description.');$items[]=[$label,$detail];}if(!$items)throw new InvalidArgumentException('Add at least one change.');
  $lock='release_notes_'.substr(hash('sha256',(string)$this->db->query('SELECT DATABASE()')->fetchColumn()),0,20);$q=$this->db->prepare('SELECT GET_LOCK(?,5)');$q->execute([$lock]);if(!$q->fetchColumn())throw new RuntimeException('Publishing is busy. Try again.');
  try{$this->db->beginTransaction();$all=$this->all();if($all&&version_compare($version,$all[0]['version'],'<='))throw new InvalidArgumentException('Append a version newer than '.$all[0]['version'].'. Existing releases are preserved.');$this->db->prepare('INSERT INTO release_notes(version,release_date,title,items_json,created_by) VALUES(?,?,?,?,?)')->execute([$version,$date,$title,json_encode($items,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$actor]);if(!(new SystemLogger($this->db))->adminAction('Published public patch notes.', $actor,['version'=>$version,'change_count'=>count($items)]))throw new RuntimeException('The release audit could not be saved.');$this->db->commit();return $version;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}finally{$this->db->prepare('SELECT RELEASE_LOCK(?)')->execute([$lock]);}
 }
}
